TLM.f("Tempora/Pent15-3",{"officium":"Feria Quarta infra Hebdomadam XV post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent15-0","from":{"Introitus":"Tempora/Pent15-0","Oratio":"Tempora/Pent15-0","Lectio":"Tempora/Pent15-0","Graduale":"Tempora/Pent15-0","Evangelium":"Tempora/Pent15-0","Offertorium":"Tempora/Pent15-0","Secreta":"Tempora/Pent15-0","Communio":"Tempora/Pent15-0","Postcommunio":"Tempora/Pent15-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 85:1; 85:2-3"},{"k":"text","la":"Inclína, Dómine, aurem tuam ad me, et exáudi me: salvum fac servum tuum, Deus meus, sperántem in te: miserére mihi, Dómine, quóniam ad te clamávi tota die."},{"k":"ref","la":"Ps 85:4"},{"k":"text","la":"Lætífica ánimam servi tui: quia ad te, Dómine, ánimam meam levávi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Inclína, Dómine, aurem tuam ad me, et exáudi me: salvum fac servum tuum, Deus meus, sperántem in te: miserére mihi, Dómine, quóniam ad te clamávi tota die."}],"Oratio":[{"k":"text","la":"Ecclésiam tuam, Dómine, miserátio continuáta mundet et múniat: et quia sine te non potest salva consístere; tuo semper múnere gubernétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas."},{"k":"ref","la":"Gal 5:25-26; 6:1-10"},{"k":"text","la":"Fratres: Si spíritu vívimus, spíritu et ambulémus. Non efficiámur inanis glóriæ cúpidi, ínvicem provocántes, ínvicem invidéntes. Fratres, et si præoccupátus fúerit homo in áliquo delícto, vos, qui spirituáles estis, hujúsmodi instrúite in spíritu lenitátis, consíderans teípsum, ne et tu tentéris. Alter alteríus ónera portáte, et sic adimplébitis legem Christi. Nam si quis exístimat se áliquid esse, cum nihil sit, ipse se sedúcit. Opus autem suum probet unusquísque, et sic in semetípso tantum glóriam habébit, et non in áltero. Unusquísque enim onus suum portábit. Commúnicet autem is, qui catechizátur verbo, ei, qui se catechízat, in ómnibus bonis. Nolíte erráre: Deus non irridétur. Quæ enim semináverit homo, hæc et metet. Quóniam qui séminat in carne sua, de carne et metet corruptiónem: qui autem séminat in spíritu, de spíritu metet vitam ætérnam. Bonum autem faciéntes, non deficiámus: témpore enim suo metémus, non deficiéntes. Ergo, dum tempus habémus, operémur bonum ad omnes, maxime autem ad domésticos fídei."}],"Graduale":[{"k":"ref","la":"Ps 91:2-3"},{"k":"text","la":"Bonum est confitéri Dómino: et psallere nómini tuo, Altíssime."},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 94:3"},{"k":"text","la":"Quóniam Deus magnus Dóminus, et Rex magnus super omnem terram. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 7:11-16"},{"k":"text","la":"In illo témpore: Ibat Jesus in civitátem, quæ vocátur Naim: et ibant cum eo discípuli ejus et turba copiósa. Cum autem appropinquáret portæ civitátis, ecce, defúnctus efferebátur fílius únicus matris suæ: et hæc vídua erat, et turba civitátis multa cum illa. Quam cum vidísset Dóminus, misericórdia motus super eam, dixit illi: Noli flere. Et accéssit et tétigit lóculum. - Hi autem, qui portábant, stetérunt - Et ait: Adoléscens, tibi dico, surge. Et resédit, qui erat mórtuus, et cœpit loqui. Et dedit illum matri suæ. Accépit autem omnes timor: et magnificábant Deum, dicéntes: Quia Prophéta magnus surréxit in nobis: et quia Deus visitávit plebem suam."}],"Offertorium":[{"k":"ref","la":"Ps 39:2; 39:3; 39:4"},{"k":"text","la":"Exspéctans exspectávi Dóminum, et respéxit me: et exaudívit deprecatiónem meam: et immísit in os meum cánticum novum, hymnum Deo nostro."}],"Secreta":[{"k":"text","la":"Tua nos, Dómine, sacramenta custodiant: et contra diabólicos semper tueántur incúrsus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 6:52"},{"k":"text","la":"Panis, quem ego dédero, caro mea est pro sǽculi vita."}],"Postcommunio":[{"k":"text","la":"Mentes nostras et córpora possídeat, quǽsumus, Dómine, doni cœléstis operátio: ut non noster sensus in nobis, sed júgiter ejus prævéniat efféctus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"0446730aaf79c895":{"t":"Ps 85, 1 i 2-3, Ps 85, 4\n(Ps 85, 1 i 2-3) Prikloni, Gospodine, svoje uho i usliši me! Spasi slugu svojega koji se uzda u te, Bože moj! Smiluj mi se, Gospodine, jer neprestano vapijem k tebi. (Ps 85, 4) Obraduj dušu sluge svojega, jer k tebi, Gospodine, uzdižem dušu svoju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 85, 1 i 2-3) Prikloni, Gospodine, svoje uho i usliši me! Spasi slugu svojega koji se uzda u te, Bože moj! Smiluj mi se, Gospodine, jer neprestano vapijem k tebi.","kn":"(Ps. 85, 1-3). Prikloni, Gofijpodine, uho svoje i usliši me; spasi slugu svojega. Bože moj, koji se uzda u Tebe; smiluj mi se, Gospodine, jer k Tebi vapijem cio dan. (Ps. 85, 4). Razveseli dušu sluge svojega, jer k Tebi, Gospodine, podižem dušu svoju. Slava Ocu.. . . Prikloni ...","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"fd919cece8b42ac3":{"t":"<i>Pomolimo se</i>.\nCrkvu tvoju, Gospodine, neprekidno milosrđe neka čisti i brani i, jer bez tebe ne može ustrajati na putu spasenja, svojom je pomoću vazda upravljaj.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Crkvu svoju, Go,spodine, neprestanim smilovanjem pročišćuj i zakriljuj, i. jer bez Tebe ne može zdrava postojati, neka se Tvojim vazda upravlja darom, po G. n.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"4dd2b22d0cf3f0dc":{"t":"Gal 5, 25-26; 6, 1-10\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo, ako živimo po duhu i ravnajmo se po duhu! Ne težimo za taštom slavom, da ne izazivamo jedan drugoga i da ne zavidimo jedan drugome. Braćo, ako koji i upadne u kakav grijeh, vi koji ste duhovni takvoga obzirno poučite, pazeći da ne biste i sami upali u kušnju. Nosite breme jedan drugoga i tako ćete ispuniti Kristov zakon. Ako netko pomišlja da je nešto a stvarno nije ništa, vara sam sebe. Neka svatko ispita svoja djela, pa će tada samo u sebi imati razlog slave, a ne u drugome, jer će svatko sam nositi svoje breme. – Koji se poučava u nauci, neka sva svoja dobra dijeli sa svojim učiteljem. Ne zavaravajte se: Bog se ne da ismjehivati! Što tko sije, to će i žeti. Tko sije za svoje tijelo, od tijela će žeti prolaznost, a tko sije za duh, od duha će žeti vječni život. Ne sustajmo činiti dobro. Ako ne klonemo, žet ćemo u svoje vrijeme. Dakle, dok imamo vremena, činimo dobro svima, posebno svojima po vjeri.","kn":"Čitanje poslanice bi. Pavla apostola Galaćanima (5, 25-26. 6, 1-10). Braćol Ako živimo po duhu, i hodajmo po duhu! Ne žudimo za taštom slavom, da izazivamo jedan drugoga i zavidimo jedan drugomu. Braćo! .'\\ko čovjek i upadne u kakav iprestupak, vi, koji ste duhovni, takvoga Inrotko poučite pazeći na sebe, da ne budeš i ti kušan. Podnosite breme jedan drugoga, i tako ćete ispuniti Kristov zakon. Jer ako tko misli, da je nešto, a nije ništa, vara samoga sebe. Svatko neka ispituje svoja djela, pa će samo tako imati slavu u sebi, a ne u drugomu, jer će svaki no.siti svoje breme. Koji je poučavan u nauci, onomu, koji ga je poučavao, neka dadne od svih dobara. Ne varajte se. Bog se ne da ismjeliavati. Što tko posije, ono će i žeti, jer tko sije za svoje tijelo, žeti će po tijelu raspadljivost, a tko sije za duh, žeti će po drthu vječni život. Ne Eustajmo čineći dobro, jer ako ne klonemo, žeti ćemo u svoje vrijeme. Dakle, dok imamo vre mena, činimo dobro svima, a najviše domaćima u vjeri.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"0cfe17da5531dafd":{"t":"Ps 91, 2-3\nDobro je slaviti Gospodina i pjevati imenu tvojemu, Svevišnji. Jutrom navješćivati tvoje milosrđe i noću tvoju vjernost.\n\nPs 94, 3\n<i>Aleluja</i>, <i>aleluja</i>.\nVeliki je Bog Gospodin i kralj velik nad svom zemljom. <i>Aleluja</i>.","kn":"(Ps. 91, 2, 3). Dobro je slaviti Gospodina i pjevati imenu Tvomu, Višnji, naviještati jutrom milosrđe Tvoje i istinu Tvoju noću.\n\nAleluja, aleluja. Jer Gospodin je veliki Bog i Kralj mećni nad svom zemljom, aleluja.","knRef":"Kniewald 1942, str. 146–147 (snimka 74) (OCR)"},"8383eb8c3946811f":{"t":"Lk 7, 11-16\nSlijedi sveto Evanđelje po Luki. U ono vrijeme išao je Isus u grad Naim. A za njim su išli njegovi učenici i mnogo naroda. Kad se približio vratima grada, gle, iznosili su mrtva jedinca majke udovice, i s njom je iz grada izlazilo mnoštvo svijeta. Kad je Isus vidi, sažali mu se te joj reče: Nemoj plakati! I nosioci stanu, a on pristupi bliže, dotakne se nosila i reče: Mladiću, tebi govorim, ustani! Tada mrtvi mladić sjedne i stade govoriti. I dade ga Isus njegovoj majci. Strah obuze sve prisutne te su slavili Boga govoreći: Velik je prorok ustao među nama, i Bog je pohodio svoj narod!","kn":"t Slijedi sveto evanđelje po Luki (7, 11-16). U ono vrijeme išao je Isus u grad Naim. A išli su s njim njegovi učenici i mnogo naroda. Kad se približio gradskim vratima, iznosili su mrtva jedinca u majke, koja je bila udovica. A izlazilo je s njom iz grada mnogo naroda. Kad ju ugleda Gospodin, sažali mu se i reče joj: Ne plači! I pristupi, dotače se nosila, a nosioci stadoše. Tada on reče: Mladiću, kažem ti: Ustani! I sjedne onaj, koji je bio mrtav, i poče govoriti, a on ga dade njegovoj majci. I sve obuze strah, i hvalili su Boga govoreći: Ustao je među nama velik prorok i Bog je pohodio svoj narod.","knRef":"Kniewald 1942, str. 566–567 (snimka 284) (OCR)"},"e91907c444cea8a2":{"t":"Ps 39, 2 i 3 i 4\nŽeljno sam očekivao Gospodina i pogledao je na me, uslišio je moju molitvu i umetnuo je u moja usta pjesmu novu, pjesmu Bogu našemu.","kn":"(Ps. 39, 2, 3, 4). Dugo sam čekao Giospodina i prlgnuo se k meni, uslišio je molbe moje i metnuo je u usta moja pjesmu novu, popijevku Bogu našemu.","knRef":"Kniewald 1942, str. 180–181 (snimka 91) (OCR)"},"e91de183224d4641":{"t":"Tvoja otajstva, Gospodine, neka nas čuvaju i od nasrtaja đavla vazda štite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvoje nas,. Gospodine, tajne čuvale i vazda branile od nasrtaja đavolskih, p,o G. n.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"e23f325e721b0af5":{"t":"Iv 6, 52\nKruh koji ću ja dati tijelo je moje za život svijeta.","kn":"(Iv. 6, 52). Kruh, koji ću ja dati, tijelo je moje za život svijeta.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"a919db06b7a07689":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nam djelovanje tvoga nebeskog dara prožme dušu i tijelo, da u nama ne prevladaju sjetila, nego neprestano djelovanje ovog otajstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Duše naše i tijela neka obuzme, molimo, Gospodine, djelovanje dara nebeskoga, da ne r slijedimo naših strasti, nego da sva naša djela uvijek pretječe u nama učinak ovog otajstva, po G. n.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"}}});
